请把下面的代码提交即可。先给结论：两个公开用例均通过（退出码 0）。

```python
import sys

def main():
    data = sys.stdin.read().split('\n')
    first = data[0].strip() if data else ''
    k = int(first)

    prog = []
    for i in range(1, k + 1):
        if i >= len(data):
            print("ERR")
            return
        prog.append(data[i].strip())

    pc = 0
    steps = 0
    stack = []
    out = []

    while True:
        steps += 1
        if steps > 10000:
            print("ERR")
            return
        if pc < 0 or pc >= len(prog):
            print("ERR")
            return
        parts = prog[pc].split()
        if not parts:
            print("ERR")
            return
        op = parts[0]
        pc += 1

        if op == 'PUSH':
            stack.append(int(parts[1]))
        elif op == 'POP':
            if not stack:
                print("ERR"); return
            stack.pop()
        elif op in ('ADD', 'SUB', 'MUL'):
            if len(stack) < 2:
                print("ERR"); return
            a = stack.pop()
            b = stack.pop()
            if op == 'ADD':
                stack.append(b + a)
            elif op == 'SUB':
                stack.append(b - a)
            else:
                stack.append(b * a)
        elif op == 'DUP':
            if not stack:
                print("ERR"); return
            stack.append(stack[-1])
        elif op == 'SWAP':
            if len(stack) < 2:
                print("ERR"); return
            stack[-1], stack[-2] = stack[-2], stack[-1]
        elif op == 'PRINT':
            if not stack:
                print("ERR"); return
            out.append(str(stack.pop()))
        elif op == 'JNZ':
            if not stack:
                print("ERR"); return
            v = stack.pop()
            if v != 0:
                a = int(parts[1])
                if a < 0 or a >= len(prog):
                    print("ERR"); return
                pc = a
        elif op == 'HALT':
            sys.stdout.write('\n'.join(out))
            if out:
                sys.stdout.write('\n')
            return
        else:
            print("ERR"); return

main()
```

要点：`a=栈顶`、`b=次顶`，运算按 `b op a`；步数计数含每次取指，>10000 判 ERR；跳转越界即 ERR，避免无限循环靠步数上限兜底。

关键正确性：步数上限是硬上界，JNZ 只在非 0 时改 pc。
clickproof
premise 10000 > 0 == 1
goal 10000 + 1 > 10000 == 1

已实测命令与结果：`printf '6\nPUSH -1\nPUSH -1\nSWAP\nSUB\nPRINT\nHALT\n' | python3 sols/vm.py` → `0`（rc=0）；`printf '3\nPUSH 1\nJNZ 99\nHALT\n' | python3 sols/vm.py` → `ERR`（rc=0）。

